"""Classified evidence from the MPRIS title corpus.

The corpus is intentionally duplicated here as static test data.  Keeping the fixture
independent from the source TSV makes the tests fail when this evidence changes.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Final


@dataclass(frozen=True)
class Fragment:
    """A raw title fragment and its expected cleaned form."""

    raw: str
    clean: str
    category: str


@dataclass(frozen=True)
class TitleCase:
    """One corpus row with its classification evidence."""

    raw_title: str
    raw_artist: str
    clean_title: str
    clean_artist: str
    category: str
    fragments: tuple[Fragment, ...] = ()
    ambiguous: bool = False
    ambiguity: str = ""
    artist_recovery: bool = False
    separator: str = "none"


CATEGORIES: Final[dict[str, str]] = {
    "variant": "Changes the recording or lyric availability.",
    "collaboration": "Credits another performer without changing the recording.",
    "platform_noise": "Identifies an upload or platform presentation.",
    "descriptor": "Names a work, series, source, or show context.",
    "alt_title": "Gives an alternate or secondary title.",
    "not_music": "Is a compilation, stream, commentary, or non-song upload.",
    "title_pair": "Presents the same title in two scripts or languages.",
    "plain": "Has no classified title fragment requiring transformation.",
}

